<?php require_once 'config.php';require_login();$page_title='Data Kartu Keluarga';$page_desc='Daftar KK dan anggota keluarga.';$rows=$pdo->query('SELECT * FROM warga ORDER BY kk,nama')->fetchAll();$groups=[];foreach($rows as $w)$groups[$w['kk']][]=$w;require 'partials/header.php';?><section class="panel"><div class="panel-head"><h3>Daftar Kartu Keluarga</h3><span class="badge"><?=count($groups)?> KK</span></div><div class="kk-grid"><?php foreach($groups as $nomor=>$members): ?><div class="kk-card"><div class="kk-head"><b>🏠 KK <?=e($nomor)?></b><span><?=count($members)?> jiwa</span></div><ul><?php foreach($members as $m): ?><li><?=e($m['nama'])?> <small><?=e($m['jk'])?> · <?=e($m['pekerjaan'])?></small></li><?php endforeach;?></ul></div><?php endforeach;?></div></section><?php require 'partials/footer.php';?>
